using namespace std;
struct Node { int val; Node* next; };
Node* push(Node* head, int v) {
  Node* n = new Node();
  n->val = v;
  n->next = head;
  return n;
}
Node* reverse(Node* head) {
  Node* prev = nullptr;
  Node* cur = head;
  while (cur != nullptr) {
    Node* nxt = cur->next;
    cur->next = prev;
    prev = cur;
    cur = nxt;
  }
  return prev;
}
int main() {
  Node* head = nullptr;
  for (int i = 1; i <= 4; i++) head = push(head, i * 10);
  for (Node* p = head; p != nullptr; p = p->next) cout << p->val << " ";
  cout << endl;
  head = reverse(head);
  for (Node* p = head; p != nullptr; p = p->next) cout << p->val << " ";
  cout << endl;
  return 0;
}
